-- Stock Machining - Material Stock
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Stock Machining - Material Stock$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Stock Machining - Material Stock$q$, 'process', 'single', false, true, true, $q$Material Stock: the stock as supplied (memory operation As Supplied; its machine has no operator and no rate). It holds the bar or plate each part is cut from (Stock Machining - Bar Stock or Plate Stock) and takes no machine time: no line is costed for it. A face of the part that lies on the stock's surface where no stock is left on it is used as supplied.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Material Stock: the stock as supplied (memory operation As Supplied; its machine has no operator and no rate). It holds the bar or plate each part is cut from (Stock Machining - Bar Stock or Plate Stock) and takes no machine time: no line is costed for it. A face of the part that lies on the stock's surface where no stock is left on it is used as supplied.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Stock Mass$q$, $q$Stock Mass (kg)$q$, $q$number$q$, $q$kg$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$0 * {Stock Mass}$q$, 2, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Stock Machining - Material Stock$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Stock Machining$q$ AND operation IN ($q$Material Stock$q$);
