$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Stock Machining - Material Stock$q$, 2, 1),
    ($q$Stock Machining - Stock Size$q$, 6, 0),
    ($q$Stock Machining - Bar Stock$q$, 14, 0),
    ($q$Stock Machining - Plate Stock$q$, 12, 0),
    ($q$Stock Machining - Band Saw$q$, 13, 1),
    ($q$Stock Machining - Scrap Credit$q$, 5, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Stock Machining$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1116: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
